// lineguard-config-report.js
// This script is designed to provide a quick snapshot of the Node.js environment
// relevant to Lineguard's execution context, aiding in debugging and reproducibility.

console.log('--- Lineguard System Configuration Report ---');
console.log(`Node.js Version: ${process.version}`);

