// This includes any API tokens or keys that might be configured for testing or local development,
// which are crucial for consistent behavior even if not directly 'consumed' by core logic.
console.log(`LINEGUARD_API_TOKEN (resolved in script context): ${process.env.LINEGUARD_API_TOKEN || 'NOT SET'}`);
